import{_ as i,l as n,o as e,c as l,v as r,p as s,x as o,d as c,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const I=JSON.parse('{"title":"DMA 一致性","description":"","frontmatter":{"title":"DMA 一致性","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dma-coherence.md","filePath":"cs/dma-coherence.md","lastUpdated":1789023840000}'),M={name:"cs/dma-coherence.md"};function h(m,a,A,_,u,D){const t=n("Mermaid");return e(),l("div",null,[a[1]||(a[1]=r('<h1 id="dma-一致性" tabindex="-1">DMA 一致性 <a class="header-anchor" href="#dma-一致性" aria-label="Permalink to &quot;DMA 一致性&quot;">​</a></h1><div class="epigraph"><p>设备 DMA 绕过 CPU 缓存：驱动必须 map/unmap 或用一致映射，否则 CPU 看见的是旧行，设备看见的是旧内存。</p><footer>—— 据 Linux DMA-API 文档；PCI 与 IOMMU 对地址翻译的说明</footer></div><p><a href="/cs/kernel-hardening">加固</a> 不管设备。<a href="/cs/nvme-driver">NVMe</a>/<a href="/cs/napi">NIC</a> 都靠 DMA。<a href="/cs/direct-map-highmem">直接映射</a> 给 CPU 看 RAM。缺口是 <strong>DMA API</strong>：流式映射、一致缓冲、IOMMU 保护。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>缓存层次对设备不可见。流式：<code>dma_map_sg</code> 前 <code>cpu_to_dev</code> 刷或作废缓存，完成后 <code>dev_to_cpu</code>。一致：<code>dma_alloc_coherent</code> 非缓存或硬件嗅探。缺口：IOMMU 把设备地址限制在 map 的窗口，防乱 DMA；bounce buffer 给不能到达高物理地址的卡。本课不把每架构 cache line 维护指令写完。</p><p><span class="marginnote">VFIO 用户态 DMA 仍走 IOMMU 域。无 IOMMU 时设备信任基等于内核。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>驱动提交 I/O：map 页给设备，门铃，完成 interrupt 后 unmap。对照 <a href="/cs/rdma-os">RDMA</a> MR：同类「允许 DMA 的窗口」。对照 <a href="/cs/write-barrier-fua">FUA</a>：那是持久；这是缓存可见性。对照 KPTI：CPU 页表，不是 IOMMU 页表。</p>',8)),(e(),s(p,null,{default:o(()=>[d(t,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20CPU%5B%22CPU%20%E7%BC%93%E5%AD%98%22%5D%20--%3E%20SYNC%5B%22dma_map%20%E5%90%8C%E6%AD%A5%22%5D%0A%20%20SYNC%20--%3E%20DEV%5B%22%E8%AE%BE%E5%A4%87%20DMA%22%5D%0A%20%20IOMMU%5B%22IOMMU%22%5D%20--%3E%20WIN%5B%22%E4%BB%85%E5%85%81%E8%AE%B8%E6%98%A0%E5%B0%84%E7%AA%97%E5%8F%A3%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>DMA API 把「设备是另一个观察者」收成驱动义务，使块与网的完成含义正确。IOMMU 把义务加上隔离。不要写成 MESI 协议课全文。与 <a href="/cs/memory-hotplug">热插拔</a>：offline 前必须无 DMA。</p><p>错误：漏 unmap 泄漏 IOMMU 表；过早 unmap 损坏。</p><p>实现上：流式映射的方向错了会静默损坏：TO_DEVICE 必须刷 CPU 缓存。IOMMU 组把无法隔离的设备绑在一起，VFIO 必须整组给同一用户。swiotlb 是 32 位 DMA 的 bounce。 读法上只引用<a href="/cs/kernel-hardening">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「内存进阶 / 回收、迁移与加固」课序里，对象是 <strong>DMA 一致性</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 DMA-BUF 跨设备共享的全部。不保证所有 virtio 的 bounce。下一课 CPU 内存标签：MTE。</p><p>版本字段会变，课序钉的是机制对象「DMA 一致性」，不是某一主线内核的结构体名。 后课默认：DMA 必须经 map 与可选 IOMMU。用标签检测空间错误，下一课 MTE。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>DMA 与 CPU 缓存要显式同步或一致映射。</li><li>IOMMU 限制设备可写的物理窗口。</li><li>内存标签是下一课。</li><li>出处：Linux DMA-API；IOMMU；PCI。</li></ul>',11))])}const E=i(M,[["render",h]]);export{I as __pageData,E as default};
